use xiom.io;
mod text_tools {
  pub mod cleaner {
    pub fn trim_spaces(s: Str) -> Int {
      s.len()
    }
  }
  pub mod counter {
    pub fn count_chars(s: Str) -> Int {
      s.len()
    }
  }

  pub use cleaner::trim_spaces;
  pub use counter::count_chars;
}

fn main() -> Int {
  use text_tools;
  let count = text_tools.count_chars("Hello");
  io.println(count.to_str());
  return 0;
}
